request.query:
query GetMetaobject($id: ID!) {
          metaobject(id: $id) { id type fields { key value } }
        }

query FetchMetaobjectReferences($id: ID!) {
      metaobject(id: $id) {
        referencedBy(first: 50) {
          edges {
            node {
              key
              namespace
              referencer {
                __typename
                ... on Product { id title }
                ... on Collection { id title }
                ... on Article { id title }
                ... on Metaobject { id type }
              }
            }
          }
          pageInfo { hasNextPage }
        }
      }
    }
